      SUBROUTINE DOCTPLCC     CALCULATES PARTIAL DERIVATIVES OF THIRD-ORDER MATRIX ELEMENTSC     WITH RESPECT TO THE MAGNETIC FIELD ON AN OCTUPOLEC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'U.CIN'CC     LOCAL VARIABLESCC------------------------------------------------------------------------C      IB = IPTOJ(2)      IK1 = IPTOJ(4)      IF (IB .NE. 0) DW2 = DPARM*UNITI(9)/(PREF*AP**3)      IF (IK1 .NE. 0) DW2 = DPARM/UNITI(8)**3      S = - 0.5*DW2*L      UV(1,1) = S*L      UV(2,1) = 2.0*S      UV(3,10) = S*L      UV(4,10) = 2.0*S      S = - .5*DW2*L**2      UV(1,2) = S*L      UV(2,2) = 3.*S      UV(3,16) = S*L      UV(4,16) = 3.0*S      S = - 0.25*DW2*L**3      UV(1,3) = S*L      UV(2,3) = 4.0*S      UV(3,19) = S*L      UV(4,19) = 4.0*S      S = - .05*DW2*L**4      UV(1,4) = S*L      UV(2,4) = 5.0*S      UV(3,20) = S*L      UV(4,20) = 5.0*S      S = 1.5*DW2*L      UV(1,8) = S*L      UV(2,8) = 2.0*S      UV(3,5) = S*L      UV(4,5) = 2.0*S      S = DW2*L**2      UV(1,14) = S*L      UV(2,14) = 3.0*S      UV(3,6) = S*L      UV(4,6) = 3.0*S      S = 0.25*DW2*L**3      UV(1,17) = S*L      UV(2,17) = 4.0*S      UV(3,7) = S*L      UV(4,7) = 4.0*S      S = .5*DW2*L**2      UV(1,9) = S*L      UV(2,9) = 3.0*S      UV(3,11) = S*L      UV(4,11) = 3.0*S      S = .5*DW2*L**3      UV(1,15) = S*L      UV(2,15) = 4.0*S      UV(3,12) = S*L      UV(4,12) = 4.0*S      S = 0.15*DW2*L**4      UV(1,18) = S*L      UV(2,18) = 5.0*S      UV(3,13) = S*L      UV(4,13) = 5.0*S      RETURN      END